(()=>{
const $=(s,p=document)=>p.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',page:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h5',layers:'m12 3 10 6-10 6L2 9z M2 13l10 6 10-6 M2 17l10 6 10-6',folder:'M3 6h7l2 3h9v11H3z',image:'M3 3h18v18H3z M3 17l6-6 5 5 3-3 4 4 M16 7h.01',mail:'M3 5h18v14H3z m0 0 9 7 9-7',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',users:'M9 3a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M2 21v-3a7 7 0 0 1 14 0v3 M17 4a4 4 0 0 1 0 8 M19 15a5 5 0 0 1 3 5',arrow:'M5 12h14 m-5-5 5 5-5 5',external:'M13 3h8v8 M21 3 10 14 M10 3H3v18h18v-7',plus:'M12 5v14 M5 12h14',edit:'m15 4 5 5 M3 21l5-1L21 7l-5-5L3 15z',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',check:'m5 12 4 4L19 6',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 3',chevron:'m9 5 7 7-7 7',logout:'M9 4H3v16h6 M9 12h12 m-4-4 4 4-4 4',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 11v6 M12 7h.01',close:'m6 6 12 12 M6 18 18 6',upload:'M12 16V3 m-5 5 5-5 5 5 M3 16v5h18v-5',copy:'M8 8h13v13H8z M16 8V3H3v13h5',menu:'M3 6h18 M3 12h18 M3 18h18',save:'M4 3h14l3 3v15H3V3z M7 3v6h10V3 M7 21v-8h10v8',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z m-5 10 3 3 6-6',down:'M12 3v18 m-6-6 6 6 6-6',up:'M12 21V3 m-6 6 6-6 6 6',blog:'M4 3h16v18H4z M8 7h8 M8 11h8 M8 15h4',money:'M3 5h18v14H3z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',faq:'M12 16v1 M8 8a4 4 0 0 1 8 0c0 3-4 2-4 5 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.page}"/></svg>`;
const names={overview:'Overview',content:'Website content',services:'Services',projects:'Projects',blog:'Blog',founders:'Founders',pricing:'Pricing',faq:'FAQ',media:'Media library',messages:'Messages',seo:'SEO',settings:'Site settings',users:'Team & access'};
const navIcons={overview:'grid',content:'page',services:'layers',projects:'folder',blog:'blog',founders:'users',pricing:'money',faq:'faq',media:'image',messages:'mail',seo:'search',settings:'settings',users:'shield'};
const LIVE=window.CLOUD_NEST_ADMIN_LIVE===true;
let data,user={name:'Cloud Nest',role:'super_admin'},authenticated=!LIVE,csrf='',revision=1,publishedRevision=1,dirty=false,route='overview',section='hero',overview={},media=[],messages=[],users=[],search='',filter='all',toastTimer;
const app=$('#app');
const titleOf=r=>r.name||r.title||r.question||'Untitled';
const date=v=>v?new Intl.DateTimeFormat('en',{day:'numeric',month:'short',year:'numeric'}).format(new Date(v)):'Not yet';
const badge=status=>`<span class="tag ${esc(status)}">${esc(status[0]?.toUpperCase()+status.slice(1))}</span>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
async function api(url,options={}){
 const headers={...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(csrf?{'X-CSRF-Token':csrf}:{}),...options.headers};
 const r=await fetch('/api'+url,{credentials:'same-origin',...options,headers});
 let value;try{value=await r.json()}catch{throw new Error('The server response could not be read. Try again.');}
 if(!r.ok){if(r.status===401&&url!='/auth/login'){login();}throw new Error(value.error||'The request could not be completed.');}return value;
}
function roleCan(key){if(user.role==='super_admin')return true;if(user.role==='support')return ['overview','messages'].includes(key);return !['messages','settings','users'].includes(key);}
function button(label,action,kind='',i=''){return `<button type="button" class="btn ${kind}" data-action="${action}">${i?icon(i):''}${esc(label)}</button>`}
function pageHeading(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">CLOUD NEST / STUDIO</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="actions">${actions}</div></div>`}
function empty(i,title,description,action=''){return `<div class="empty">${icon(i)}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`}
function shell(){
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#overview"><img src="/assets/cloud-nest-logo.png" alt=""><span>Cloud<em>Nest.</em></span></a><div class="workspace-tag"><span>CN</span><div>Cloud Nest Studio<small>Website workspace</small></div></div><nav aria-label="Admin navigation"><div class="nav-label">WORKSPACE</div>${Object.keys(names).filter(roleCan).map((key,i)=>`${key==='media'?'<div class="nav-label">MANAGE</div>':''}<a href="#${key}" class="nav-item ${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${icon(navIcons[key])}${names[key]}</a>`).join('')}</nav><div class="sidebar-foot"><div class="profile"><span class="avatar">${esc(user.name.split(' ').map(v=>v[0]).slice(0,2).join(''))}</span><div><strong>${esc(user.name)}</strong><small>${LIVE?esc(user.role.replace('_',' ')):'Design preview'}</small></div>${LIVE?`<button class="signout" data-action="logout" aria-label="Sign out">${icon('logout')}</button>`:''}</div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb"><button class="menu-toggle" data-action="menu" aria-label="Toggle admin navigation" aria-expanded="false">${icon('menu')}</button><span>Workspace</span>${icon('chevron')}<b>${names[route]}</b></div><div class="top-actions"><span class="tag">${LIVE?'Admin workspace':'Preview workspace'}</span><a href="/" target="_blank" rel="noopener" class="top-link">View website ${icon('external')}</a><span class="avatar">CN</span></div></header>${!LIVE?`<div class="preview-banner">${icon('info')}<span><strong>Preview mode.</strong> Edits stay in this tab. Connect the backend to update the public website.</span><button data-action="connection">Connection details</button></div>`:''}<main class="workspace" id="workspace" tabindex="-1">${page()}<div class="footer-note"><span>Cloud Nest Studio · ${new Date().getFullYear()}</span><span>${LIVE?'Your workspace. Your next chapter.':'Design preview · no live changes'}</span></div></main></div>`;
 bindForms();
}
function stat(label,value,note,i){return `<div class="stat"><div class="stat-label">${esc(label)}${icon(i)}</div><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`}
function page(){
 if(route==='overview')return dashboard();
 if(['content','settings','seo'].includes(route))return contentEditor();
 if(route==='media')return mediaPage();
 if(route==='messages')return messagesPage();
 if(route==='users')return usersPage();
 return collectionPage();
}
function dashboard(){
 const hasContent=roleCan('content');const services=data.services.filter(r=>r.status==='published').length;
 return pageHeading('Your studio, at a glance.','Make something great. Keep every detail in your hands.',hasContent?button('Preview website','preview','','eye')+button('Edit homepage','edit-home','primary','edit'):'')+`<div class="stats">${stat('Content sections',7,'Homepage to FAQ','page')}${stat('Active services',services,`${data.services.length} services in your workspace`,'layers')}${stat('Published projects',data.projects.filter(r=>r.status==='published').length,'Your portfolio, in one place','folder')}${stat('New enquiries',LIVE?overview.messages?.unread||0:'—',LIVE?'Waiting for your reply':'Available after backend connection','mail')}</div><div class="dashboard-grid"><div class="column">${hasContent?`<div class="site-card"><div class="eyebrow">YOUR WEBSITE</div><h2>${esc(data.home.line1)}<br>${esc(data.home.line2)} ${esc(data.home.line3)}</h2>${button('Open content editor','edit-home','','arrow')}<span class="site-card-footer">cloud-nest-studio</span></div><div class="panel"><div class="panel-head"><h2>Make it yours</h2><small>Quick edits</small></div>${[['content','Homepage','Headlines, images & calls to action'],['services','Services','What you do. How you do it.'],['blog','Journal','Stories, ideas & perspectives'],['founders','The founders','People, roles & contact details']].map(([key,label,desc])=>`<a href="#${key}" class="editor-row"><span class="section-icon">${icon(navIcons[key])}</span><div><strong>${label}</strong><small>${desc}</small></div><span class="row-action">${icon('arrow')}</span></a>`).join('')}</div>`:''}<div class="panel"><div class="panel-head"><h2>Recent enquiries</h2>${roleCan('messages')?'<a href="#messages" class="top-link">View inbox '+icon('arrow')+'</a>':''}</div>${overview.recentMessages?.length?overview.recentMessages.map(m=>`<a href="#messages" class="editor-row"><span class="section-icon">${icon('mail')}</span><div><strong>${esc(m.name)}</strong><small>${esc(m.subject)}</small></div><span class="row-action">${badge(m.status)}</span></a>`).join(''):empty('mail',LIVE?'No enquiries yet':'Your inbox belongs here',LIVE?'New website enquiries will appear here.':'Messages appear here once the contact form is connected.')}</div></div><div class="column"><div class="panel"><div class="panel-head"><h2>Workspace status</h2>${badge(LIVE?'published':'draft')}</div><div class="checklist">${[['check','Website content','Your current Cloud Nest content is loaded.',false],[LIVE?'check':'clock','Admin authentication',LIVE?'Secure login and role permissions are active.':'Ready for backend deployment.',!LIVE],[LIVE?'check':'clock','Database & publishing',LIVE?`Published revision ${publishedRevision}.`:'Connect PostgreSQL to enable live updates.',!LIVE],[LIVE?'check':'clock','Contact inbox',LIVE?'Website enquiries are stored in your inbox.':'Contact messages need the backend connection.',!LIVE]].map(([i,t,d,p])=>`<div class="check ${p?'pending':''}">${icon(i)}<div><p>${t}</p><small>${d}</small></div></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><h2>Recent activity</h2>${icon('clock')}</div>${overview.activity?.length?`<div class="activity">${overview.activity.map(a=>`<div class="activity-row">${esc(a.action)}<small>${esc(a.actor)} · ${date(a.created_at)}</small></div>`).join('')}</div>`:empty('clock','A fresh start',LIVE?'Saved edits and published updates will appear here.':'Live editing history will appear after connection.')}</div>${hasContent?`<div class="section-note"><strong>A little room to experiment.</strong><br>Save your draft, preview it on desktop or mobile, then publish when it feels right.</div>`:''}</div></div>`;
}
const fields={
 home:{hero:[['label','Top label'],['line1','Headline · line 1'],['line2','Headline · line 2'],['line3','Headline · line 3'],['description','Supporting paragraph','textarea'],['image','Hero image','image'],['buttonText','Primary button text'],['buttonLink','Primary button link','url'],['secondaryText','Secondary button text'],['secondaryLink','Secondary button link','url']],about:[['aboutTitle','Heading'],['aboutDescription','Description','textarea']],services:[['servicesTitle','Heading'],['servicesDescription','Description','textarea']],projects:[['projectsTitle','Heading'],['projectsDescription','Description','textarea']],contact:[['contactTitle','Heading'],['contactDescription','Description','textarea']]},
 services:[['name','Service name'],['shortDescription','Short description','textarea'],['description','Full description','textarea'],['tags','Tags · separate with a dot'],['icon','Icon character'],['image','Service image','image'],['deliverables','Deliverables · one per line','textarea'],['process','Process · one step per line','textarea']],
 projects:[['title','Project title'],['client','Client'],['category','Category'],['url','Project URL','url'],['description','Description','textarea'],['image','Cover image','image'],['gallery','Gallery URLs · one per line','textarea'],['technologies','Technologies']],
 blog:[['title','Article title'],['slug','URL slug'],['category','Category'],['excerpt','Short introduction','textarea'],['body','Article text · separate paragraphs with a blank line','textarea'],['image','Cover image','image']],
 founders:[['name','Full name'],['role','Role'],['email','Email address','email'],['phone','Phone number'],['image','Founder image','image']],
 pricing:[['name','Plan name'],['label','Small label'],['price','Price or quote text'],['note','Pricing note'],['description','Description','textarea'],['features','Included features · one per line','textarea'],['recommended','Recommended plan','checkbox']],
 faq:[['question','Question'],['answer','Answer','textarea']],
 settings:[['companyName','Company name'],['tagline','Footer description'],['logo','Logo','image'],['favicon','Favicon','image'],['email','Contact email','email'],['phone','Contact phone'],['address','Address'],['facebook','Facebook','url'],['instagram','Instagram','url'],['linkedin','LinkedIn','url'],['youtube','YouTube','url'],['copyright','Copyright text']],
 seo:[['title','SEO title'],['description','Meta description','textarea'],['slug','Page path'],['ogTitle','Social sharing title'],['ogDescription','Social sharing description','textarea'],['ogImage','Social sharing image','image'],['keywords','Keywords']]
};
function field([key,label,type='text'],value){
 const id='field-'+key;const full=['textarea','image'].includes(type);const max=['body','description','deliverables','process','features','answer','gallery'].includes(key)?20000:2048;
 if(type==='checkbox')return `<label class="field check-field full" for="${id}"><input id="${id}" name="${key}" type="checkbox" ${value?'checked':''}>${label}</label>`;
 const input=type==='textarea'?`<textarea id="${id}" name="${key}" rows="${key==='body'?12:4}" maxlength="${max}">${esc(value)}</textarea>`:`<input id="${id}" name="${key}" value="${esc(value)}" type="${type==='email'?'email':'text'}" maxlength="${max}" ${route==='seo'&&key==='slug'?'readonly aria-label="Homepage path, fixed at slash"':''} ${['name','title','question'].includes(key)?'required':''}>`;
 return `<div class="field ${full?'full':''}"><label for="${id}">${label}</label>${type==='image'?`<div class="input-actions">${input}<button class="btn" type="button" data-action="pick-image" data-field="${key}">${icon('image')}Choose</button></div><small>Choose from media, or paste an HTTPS image URL.</small>`:input}${type==='url'?'<small>Use an https:// link or a section such as #contact.</small>':''}</div>`;
}
function contentEditor(){
 const isHome=route==='content',key=isHome?'home':route;const defs=isHome?fields.home[section]:fields[key];
 const labels={hero:'Hero section',about:'About Cloud Nest',services:'Services heading',projects:'Portfolio heading',contact:'Contact section'};
 return pageHeading(isHome?'Make every word count.':names[route],isHome?'Edit your website without touching the code.':route==='seo'?'Control how your homepage appears in search and sharing.':'Keep your brand and contact details in one place.',button('Preview','preview','','eye'))+`<div class="editor-layout">${isHome?`<div class="section-tabs" role="navigation" aria-label="Homepage sections">${Object.keys(labels).map(k=>`<button class="${section===k?'active':''}" data-action="section" data-section="${k}">${labels[k]}</button>`).join('')}</div>`:`<div class="section-note">${route==='seo'?'Homepage metadata. Individual journal articles keep their own title and introduction.':'These details are shared across your public website.'}</div>`}<div><form class="panel form-panel" id="content-form"><h2>${isHome?labels[section]:names[route]}</h2><p>${isHome?'Keep it clear. Make it unmistakably Cloud Nest.':'Changes are saved to a draft before publishing.'}</p><div class="fields">${defs.map(f=>field(f,data[key][f[0]])).join('')}</div>${route==='seo'?`<div class="inline-preview"><small>Cloud Nest</small><h3>${esc(data.seo.title)}</h3><p>${esc(data.seo.description)}</p></div>`:''}<div class="form-bottom"><span class="status-line">${icon('clock')}${LIVE?`Draft revision ${revision}`:'Saved in this tab only'}</span><div class="actions"><button class="btn primary" type="submit">${icon('save')}${LIVE?'Save draft':'Save preview'}</button>${button('Publish','publish','','upload')}</div></div><p class="dialog-error" role="alert"></p></form></div></div>`;
}
function collectionPage(){
 const items=data[route].filter(r=>(filter==='all'||r.status===filter)&&JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));
 const singular={services:'service',projects:'project',blog:'article',founders:'founder',pricing:'plan',faq:'question'}[route];
 const desc={services:'Shape your offer. Set the order. Publish when ready.',projects:'Give your best work a place to shine.',blog:'Fresh perspectives, managed in one place.',founders:'The people and conversations behind Cloud Nest.',pricing:'Clear packages for every stage of growth.',faq:'Make the next step easier for your visitors.'};
 return pageHeading(names[route],desc[route],button('Preview','preview','','eye')+button('Add '+singular,'add','primary','plus'))+`<div class="panel"><div class="toolbar"><label class="search">${icon('search')}<span class="sr-only">Search ${names[route]}</span><input id="list-search" placeholder="Search ${names[route].toLowerCase()}…" value="${esc(search)}"></label><label><span class="sr-only">Filter status</span><select id="status-filter" class="filter"><option value="all">All statuses</option><option value="published" ${filter==='published'?'selected':''}>Published</option><option value="draft" ${filter==='draft'?'selected':''}>Draft</option></select></label><span class="muted tiny">${items.length} items</span></div>${items.length?`<div class="table-wrap"><table><thead><tr><th>Order</th><th>${singular}</th><th>Status</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${items.map(r=>`<tr><td class="record-num">${String(data[route].indexOf(r)+1).padStart(2,'0')}</td><td><div class="record-title">${esc(titleOf(r))}</div><div class="record-desc">${esc(r.shortDescription||r.excerpt||r.description||r.answer||r.email||'')}</div></td><td>${badge(r.status)}</td><td><div class="row-tools"><button class="icon-btn" data-action="move-up" data-id="${esc(r.id)}" aria-label="Move ${esc(titleOf(r))} up" ${data[route].indexOf(r)===0?'disabled':''}>${icon('up')}</button><button class="icon-btn" data-action="move-down" data-id="${esc(r.id)}" aria-label="Move ${esc(titleOf(r))} down" ${data[route].indexOf(r)===data[route].length-1?'disabled':''}>${icon('down')}</button><button class="icon-btn" data-action="edit" data-id="${esc(r.id)}" aria-label="Edit ${esc(titleOf(r))}">${icon('edit')}</button><button class="icon-btn" data-action="delete" data-id="${esc(r.id)}" aria-label="Delete ${esc(titleOf(r))}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty(navIcons[route],search||filter!=='all'?'No matches':'Your next '+singular+' starts here',search?'Try a different search.':'Add a '+singular+' and preview it before publishing.',!search?button('Add '+singular,'add','','plus'):'')}</div><div class="form-bottom"><span>${LIVE?`Saved draft · revision ${revision}`:'Preview workspace · edits stay in this tab'}</span>${button('Publish website','publish','primary','upload')}</div>`;
}
function mediaPage(){const list=media.filter(m=>(filter==='all'||m.mime_type===filter)&&m.filename.toLowerCase().includes(search.toLowerCase()));return pageHeading('A home for your visuals.','Upload, organise and reuse the images that tell your story.',button('Upload image','upload','primary','upload'))+`<div class="panel"><div class="toolbar"><label class="search">${icon('search')}<span class="sr-only">Search images</span><input id="list-search" placeholder="Search images…" value="${esc(search)}"></label><select class="filter" id="status-filter" aria-label="Image format"><option value="all">All images</option>${['image/png','image/jpeg','image/webp'].map(v=>`<option value="${v}" ${filter===v?'selected':''}>${v.split('/')[1].toUpperCase()}</option>`).join('')}</select></div>${list.length?`<div class="media-grid">${list.map(m=>`<article class="media-card"><img src="${esc(m.url)}" alt="${esc(m.alt_text||m.filename)}" loading="lazy"><div class="media-info"><strong>${esc(m.filename)}</strong><small>${esc(m.mime_type.split('/')[1].toUpperCase())}${m.size?' · '+Math.ceil(m.size/1024)+' KB':''}</small><div class="media-buttons"><button class="btn" data-action="copy-media" data-id="${esc(m.id)}">Copy URL</button>${LIVE?`<button class="btn" data-action="edit-media" data-id="${esc(m.id)}">Edit</button>`:''}</div></div></article>`).join('')}</div>`:empty('image','No images found','Upload a PNG, JPEG or WebP image to begin.')}</div>`}
function messagesPage(){const list=messages.filter(m=>(filter==='all'||m.status===filter)&&JSON.stringify(m).toLowerCase().includes(search.toLowerCase()));return pageHeading('Good things start here.','Read enquiries and keep every conversation moving.')+(!LIVE?'<div class="notice">This inbox is a preview. No messages have been received or stored here.</div>':'')+`<div class="panel"><div class="toolbar"><label class="search">${icon('search')}<span class="sr-only">Search messages</span><input id="list-search" placeholder="Search enquiries…" value="${esc(search)}"></label><select id="status-filter" class="filter" aria-label="Message status"><option value="all">All statuses</option>${['new','read','replied','closed'].map(v=>`<option value="${v}" ${filter===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>From</th><th>Subject</th><th>Status</th><th>Received</th><th>Action</th></tr></thead><tbody>${list.map(m=>`<tr><td><div class="record-title">${esc(m.name)}</div><div class="record-desc">${esc(m.email)}</div></td><td>${esc(m.subject)}</td><td>${badge(m.status)}</td><td>${date(m.created_at)}</td><td><button class="btn" data-action="message" data-id="${m.id}">View</button></td></tr>`).join('')}</tbody></table></div>`:empty('mail','Your inbox is clear',LIVE?'New enquiries from your website will appear here.':'Connect the backend to receive and manage website enquiries.')}</div>`}
function usersPage(){return pageHeading('The right people. The right access.','Manage who can shape your website.',button('Add administrator','add-user','primary','plus'))+(!LIVE?'<div class="notice">No admin accounts are active in preview mode. Your first Super Admin is created securely during backend setup.</div>':'')+`<div class="panel"><div class="panel-head"><h2>Workspace administrators</h2>${LIVE?button('Change my password','password'):''}</div>${users.length?`<div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.role.replace('_',' '))}</td><td>${badge(u.active?'published':'draft')}</td><td>${u.id===user.id?'You':`<button class="btn" data-action="edit-user" data-id="${u.id}">Manage</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('shield','A private workspace','Super Admin manages everything. Editors manage content and media. Support manages messages.')}</div><div class="section-note"><strong>Access is checked on the server.</strong> Hiding a button is never the only thing protecting your website.</div>`}
function bindForms(){
 $('#content-form')?.addEventListener('input',()=>{dirty=true});
 $('#content-form')?.addEventListener('submit',async e=>{e.preventDefault();const submit=e.currentTarget.querySelector('[type=submit]');if(submit.disabled)return;submit.disabled=true;const key=route==='content'?'home':route;const defs=route==='content'?fields.home[section]:fields[key];const before=structuredClone(data[key]);const values=new FormData(e.currentTarget);for(const [k,,type]of defs)data[key][k]=type==='checkbox'?values.has(k):String(values.get(k)||'');try{await save();shell()}catch(err){if(data)data[key]=before;$('.dialog-error',e.target).textContent=err.message;submit.disabled=false}});
 $('#list-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;search=e.target.value;shell();$('#list-search').focus();$('#list-search').setSelectionRange(pos,pos)});
 $('#status-filter')?.addEventListener('change',e=>{filter=e.target.value;shell()});
}
async function save(){
 if(LIVE){const r=await api('/admin/content',{method:'PUT',body:JSON.stringify({content:data,revision})});revision=r.revision;}
 else sessionStorage.setItem('cn-admin-draft',JSON.stringify(data));
 dirty=false;toast(LIVE?'Draft saved. Publish when you’re ready.':'Preview saved in this tab. The live website is unchanged.');
}
function modal(title,body,footer=''){
 const d=$('#editor-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="editor-title">${esc(title)}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close">${icon('close')}</button></div><div class="dialog-body">${body}${footer}</div>`;if(!d.open)d.showModal();return d;
}
function confirmAction(title,description,label,fn){const d=$('#confirm-dialog');d.innerHTML=`<div class="dialog-body"><h2 id="confirm-title">${esc(title)}</h2><p class="muted">${esc(description)}</p><div class="dialog-footer"><button class="btn" data-action="close-confirm">Cancel</button><button class="btn primary" id="confirm-go">${esc(label)}</button></div><p class="dialog-error" role="alert"></p></div>`;d.showModal();$('#confirm-go').onclick=async()=>{const b=$('#confirm-go');b.disabled=true;try{await fn();d.close()}catch(e){$('.dialog-error',d).textContent=e.message;b.disabled=false}}}
function editRecord(id){
 const key=route,existing=data[key].find(r=>r.id===id),r=structuredClone(existing||{id:crypto.randomUUID(),status:'draft'});
 const d=modal(existing?'Edit '+titleOf(existing):'Add '+({services:'service',projects:'project',blog:'article',founders:'founder',pricing:'plan',faq:'question'}[key]),`<form id="record-form"><div class="fields">${fields[key].map(f=>field(f,r[f[0]])).join('')}<label class="field">Visibility<select name="status"><option value="draft" ${r.status==='draft'?'selected':''}>Draft — hidden from visitors</option><option value="published" ${r.status==='published'?'selected':''}>Published — visible after publishing</option></select></label></div><p class="dialog-error" role="alert"></p><div class="dialog-footer"><button class="btn" type="button" data-action="close-dialog">Cancel</button><button class="btn primary" type="submit">${LIVE?'Save draft':'Save preview'}</button></div></form>`);
 $('#record-form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);for(const [k,,t]of fields[key])r[k]=t==='checkbox'?fd.has(k):String(fd.get(k)||'');r.status=fd.get('status');if(key==='blog'&&!r.slug)r.slug=(r.title||'article').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');const before=structuredClone(data[key]);if(existing)data[key][data[key].findIndex(v=>v.id===id)]=r;else data[key].push(r);const submit=e.currentTarget.querySelector('[type=submit]');submit.disabled=true;try{await save();d.close();shell()}catch(err){data[key]=before;$('.dialog-error',d).textContent=err.message;submit.disabled=false}};
}
function connection(){modal('Connect your live workspace',`<p class="muted">Your admin design and backend code are prepared. Publishing needs these connections:</p><div class="checklist"><div class="check pending">${icon('clock')}<div><p>PostgreSQL database</p><small>Stores content, users and enquiries.</small></div></div><div class="check pending">${icon('clock')}<div><p>Backend hosting + persistent media storage</p><small>Runs secure login, uploads and the publishing API.</small></div></div><div class="check pending">${icon('clock')}<div><p>First Super Admin account</p><small>Created privately after deployment. There is no default password.</small></div></div></div><p class="section-note">Until connected, you can edit and preview the design in this tab. The public website is unchanged.</p>${window.CLOUD_NEST_API_ORIGIN?`<div class="dialog-footer"><a class="btn primary" href="${esc(window.CLOUD_NEST_API_ORIGIN)}/admin/">Open live admin ${icon('external')}</a></div>`:''}`)}
function preview(){sessionStorage.setItem('cn-preview-content',JSON.stringify(data));const d=$('#preview-dialog');d.innerHTML=`<div class="dialog-head"><h2>Website draft preview</h2><div class="actions"><button class="btn" data-action="preview-size">Desktop / mobile</button><button class="icon-btn" data-action="close-preview" aria-label="Close preview">${icon('close')}</button></div></div><iframe title="Cloud Nest draft website" src="/?preview=admin"></iframe>`;d.showModal()}
// Large originals are prepared locally; the server still bounds stored uploads.
async function prepareMediaImage(file){
 const maxStored=8*1024*1024;
 if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Choose a PNG, JPEG or WebP image.');
 if(file.size>100*1024*1024)throw new Error('Choose an image up to 100 MB.');
 if(file.size<=maxStored)return file;
 const url=URL.createObjectURL(file),img=new Image();
 let canvas;
 try{
  await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('This image could not be opened. Please export it as PNG, JPEG or WebP.'));img.src=url;});
  let scale=Math.min(1,4096/Math.max(img.naturalWidth,img.naturalHeight));
  canvas=document.createElement('canvas');
  for(let attempt=0;attempt<7;attempt++){
   canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));
   canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));
   const ctx=canvas.getContext('2d');
   if(!ctx)throw new Error('Your browser could not prepare this image.');
   ctx.drawImage(img,0,0,canvas.width,canvas.height);
   const blob=await new Promise(resolve=>canvas.toBlob(resolve,file.type,0.88));
   if(!blob||blob.type!==file.type)throw new Error('Your browser could not save this image format. Try JPEG or PNG.');
   if(blob.size<=maxStored)return new File([blob],file.name,{type:blob.type,lastModified:file.lastModified});
   scale*=0.7;
  }
  throw new Error('This image is still too large. Please export a smaller copy.');
 }finally{URL.revokeObjectURL(url);img.src='';if(canvas){canvas.width=1;canvas.height=1;}}
}
async function uploadMedia(replaceId){if(!LIVE)return connection();const d=modal(replaceId?'Replace image':'Upload an image',`<form id="upload-form"><p class="muted">PNG, JPEG or WebP · originals up to 100 MB. Large images are automatically resized and compressed for the website${replaceId?' · same format as the original':''}</p><br><input class="file-input" name="file" type="file" accept="image/png,image/jpeg,image/webp" required><p class="dialog-error" role="alert"></p><div class="dialog-footer"><button class="btn primary" type="submit">Upload image</button></div></form>`);$('#upload-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const b=e.target.querySelector('button');b.disabled=true;try{$('.dialog-error',d).textContent='';b.textContent='Preparing image…';const prepared=await prepareMediaImage(f.get('file'));f.set('file',prepared,prepared.name);b.textContent='Uploading…';await api('/admin/media'+(replaceId?'/'+replaceId+'/replace':''),{method:'POST',body:f});media=await api('/admin/media');d.close();shell();toast('Image uploaded.')}catch(err){$('.dialog-error',d).textContent=err.message;b.disabled=false;b.textContent='Upload image'}}}
async function pickImage(key){
 // Keep the record form intact while the selection dialog is open.
 const d=$('#confirm-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="confirm-title">Choose an image</h2><button class="icon-btn" data-action="close-confirm" aria-label="Close">${icon('close')}</button></div><div class="media-grid">${media.map(m=>`<button class="media-card" data-pick="${esc(m.url)}"><img src="${esc(m.url)}" alt="${esc(m.filename)}"><span class="media-info">${esc(m.filename)}</span></button>`).join('')}</div>${!media.length?empty('image','No images yet','Upload an image in Media library, then return here.'):''}`;d.showModal();d.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const form=$('#editor-dialog').open?$('#editor-dialog'):$('#content-form');const input=form.querySelector(`[name="${key}"]`);if(input){input.value=b.dataset.pick;input.dispatchEvent(new Event('input',{bubbles:true}))}d.close()});
}
function message(id){const m=messages.find(x=>x.id===id);const d=modal(m.subject||'Project enquiry',`<div class="message-meta"><strong>${esc(m.name)}</strong> · <a href="mailto:${esc(m.email)}">${esc(m.email)}</a><br>${esc(m.company)} ${esc(m.phone)}<br>Received ${date(m.created_at)} · Email notification: ${esc(m.email_status.replaceAll('_',' '))}</div><div class="message-body">${esc(m.message)}</div><form id="message-form"><label class="field">Status<select name="status">${['new','read','replied','closed'].map(v=>`<option value="${v}" ${v===m.status?'selected':''}>${v}</option>`).join('')}</select></label><div class="dialog-footer"><button class="btn danger" type="button" data-action="delete-message" data-id="${m.id}">Delete</button><a class="btn" href="mailto:${esc(m.email)}">Reply by email</a><button class="btn primary">Save status</button></div><p class="dialog-error" role="alert"></p></form>`);$('#message-form').onsubmit=async e=>{e.preventDefault();try{await api('/admin/messages/'+id,{method:'PUT',body:JSON.stringify({status:new FormData(e.target).get('status')})});messages=await api('/admin/messages');d.close();shell();toast('Message updated.')}catch(err){$('.dialog-error',d).textContent=err.message}}}
function userEditor(id){if(!LIVE)return connection();const u=users.find(v=>v.id===id);const d=modal(u?'Manage access':'Add administrator',`<form id="user-form"><div class="fields">${!u?field(['name','Full name'],'')+field(['email','Email','email'],'')+'<label class="field full">Initial password<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><small>At least 12 characters. Share securely with this person.</small></label>':`<p class="field full">${esc(u.name)} · ${esc(u.email)}</p>`}<label class="field">Role<select name="role">${['super_admin','editor','support'].map(r=>`<option value="${r}" ${u?.role===r?'selected':''}>${r.replace('_',' ')}</option>`).join('')}</select></label>${u?`<label class="field check-field"><input type="checkbox" name="active" ${u.active?'checked':''}>Active account</label>`:''}</div><div class="dialog-footer"><button class="btn primary">Save administrator</button></div><p class="dialog-error" role="alert"></p></form>`);$('#user-form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),body=Object.fromEntries(fd);if(u)body.active=fd.has('active');try{await api('/admin/users'+(u?'/'+id:''),{method:u?'PUT':'POST',body:JSON.stringify(body)});users=await api('/admin/users');d.close();shell();toast('Administrator saved.')}catch(err){$('.dialog-error',d).textContent=err.message}}}
async function navigate(){if(LIVE&&!authenticated){login();return;}const next=location.hash.slice(1)||'overview';if(!names[next]||!roleCan(next)){location.hash='overview';return}if(next===route&&dirty)return;if(dirty){location.hash=route;confirmAction('Leave unsaved edits?','Your unsaved form changes will be discarded.','Leave editor',()=>{dirty=false;location.hash=next});return;}route=next;search='';filter='all';try{if(LIVE){if(route==='media')media=await api('/admin/media');if(route==='messages')messages=await api('/admin/messages');if(route==='users')users=await api('/admin/users');if(route==='overview')overview=await api('/admin/overview');}}catch(e){toast(e.message);return}shell()}
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 try{
  if(a==='menu'){const open=$('.sidebar').classList.toggle('open');b.setAttribute('aria-expanded',String(open));}
  if(a==='close-dialog')$('#editor-dialog').close();if(a==='close-confirm')$('#confirm-dialog').close();if(a==='close-preview')$('#preview-dialog').close();
  if(a==='connection')connection();if(a==='edit-home'){section='hero';location.hash='content'}
  if(a==='section'){if(dirty){toast('Save your current edits before changing sections.');return;}section=b.dataset.section;shell()}
  if(a==='preview'){if(dirty){toast('Save this form before previewing.');return;}preview()}
  if(a==='preview-size')$('#preview-dialog').classList.toggle('mobile');
  if(a==='add'||a==='edit')editRecord(id);
  if(a==='delete')confirmAction('Delete this item?','It will be removed from the draft. Publish to remove it from the public website.','Delete item',async()=>{const old=data[route];data[route]=old.filter(r=>r.id!==id);try{await save();shell()}catch(e){data[route]=old;throw e}});
  if(a==='move-up'||a==='move-down'){const old=[...data[route]],list=data[route],i=list.findIndex(r=>r.id===id),j=i+(a==='move-up'?-1:1);if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];try{await save();shell()}catch(e){data[route]=old;throw e}}
  if(a==='publish'){if(!LIVE)return connection();if(dirty)return toast('Save your edits before publishing.');confirmAction('Publish your website?','Your saved draft will replace the content visitors see.','Publish now',async()=>{const r=await api('/admin/publish',{method:'POST',body:JSON.stringify({revision})});publishedRevision=r.published_revision;shell();toast('Your website content is now published.')})}
  if(a==='upload')uploadMedia();if(a==='pick-image')pickImage(b.dataset.field);
  if(a==='copy-media'){const m=media.find(v=>v.id===id);await navigator.clipboard.writeText(new URL(m.url,location.origin).href);toast('Image URL copied.')}
  if(a==='edit-media'){const m=media.find(v=>v.id===id);const d=modal('Edit image',`<form id="media-form"><div class="fields">${field(['filename','Image name'],m.filename)}${field(['alt_text','Alternative text'],m.alt_text)}</div><div class="dialog-footer"><button class="btn danger" type="button" data-action="delete-media" data-id="${id}">Delete</button><button class="btn" type="button" data-action="replace-media" data-id="${id}">Replace image</button><button class="btn primary">Save</button></div><p class="dialog-error" role="alert"></p></form>`);$('#media-form').onsubmit=async ev=>{ev.preventDefault();try{await api('/admin/media/'+id,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(ev.target)))});media=await api('/admin/media');d.close();shell()}catch(err){$('.dialog-error',d).textContent=err.message}}}
  if(a==='replace-media')uploadMedia(id);
  if(a==='delete-media')confirmAction('Delete this image?','Images used in saved or published content cannot be deleted.','Delete image',async()=>{await api('/admin/media/'+id,{method:'DELETE'});media=await api('/admin/media');$('#editor-dialog').close();shell()});
  if(a==='message')message(id);
  if(a==='delete-message')confirmAction('Delete this enquiry?','This permanently removes the stored message.','Delete enquiry',async()=>{await api('/admin/messages/'+id,{method:'DELETE'});messages=await api('/admin/messages');$('#editor-dialog').close();shell()});
  if(a==='add-user'||a==='edit-user')userEditor(id);
  if(a==='logout'){await api('/auth/logout',{method:'POST',body:'{}'});csrf='';login()}
  if(a==='password'){const d=modal('Change your password',`<form id="password-form"><div class="fields"><label class="field full">Current password<input type="password" name="currentPassword" autocomplete="current-password" required></label><label class="field full">New password<input type="password" name="password" autocomplete="new-password" minlength="12" maxlength="128" required></label></div><div class="dialog-footer"><button class="btn primary">Change password</button></div><p class="dialog-error" role="alert"></p></form>`);$('#password-form').onsubmit=async ev=>{ev.preventDefault();try{await api('/admin/password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(ev.target)))});d.close();login();toast('Password changed. Sign in again.')}catch(err){$('.dialog-error',d).textContent=err.message}}}
 }catch(err){toast(err.message)}
});
window.addEventListener('hashchange',navigate);window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
function login(){authenticated=false;csrf='';dirty=false;data=null;messages=[];users=[];media=[];overview={};sessionStorage.removeItem('cn-preview-content');document.querySelectorAll('dialog[open]').forEach(d=>d.close());app.innerHTML=`<main class="login"><section class="login-story"><a class="brand" href="/"><img src="/assets/cloud-nest-logo.png" alt=""><span>Cloud<em>Nest.</em></span></a><div><div class="eyebrow">YOUR STUDIO. YOUR NEXT CHAPTER.</div><h1>Beautiful things<br>start here.</h1><p>The workspace behind Cloud Nest.</p></div><small>Cloud Nest Studio</small></section><section class="login-main"><form class="login-form" id="login-form"><div class="eyebrow">CLOUD NEST ADMIN</div><h2>Welcome back.</h2><p>Sign in to manage your website.</p><label class="field">Email address<input name="email" type="email" autocomplete="username" required></label><label class="field">Password<input name="password" type="password" autocomplete="current-password" required></label><label class="field check-field"><input type="checkbox" name="remember">Remember me for 7 days</label><p class="dialog-error" role="alert"></p><button class="btn primary">Sign in ${icon('arrow')}</button><p class="login-extra">Need a password reset? Ask your hosting administrator to reset your account securely.</p><a class="top-link" href="/">Back to website ${icon('external')}</a></form></section></main>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const fd=new FormData(e.target);const r=await api('/auth/login',{method:'POST',body:JSON.stringify({email:fd.get('email'),password:fd.get('password'),remember:fd.has('remember')})});user=r.user;csrf=r.csrf;authenticated=true;await loadLive();await navigate()}catch(err){$('.dialog-error',e.target).textContent=err.message;b.disabled=false}}}
async function loadLive(){if(roleCan('content')){const r=await api('/admin/content');data=r.draft;revision=r.revision;publishedRevision=r.published_revision;media=await api('/admin/media');}else{data=(await api('/public/content')).content;}overview=await api('/admin/overview');}
async function start(){try{const r=await fetch('/content-seed.json');if(!r.ok)throw new Error('Website content could not be loaded.');data=await r.json();if(LIVE){try{const me=await api('/auth/me');user=me.user;csrf=me.csrf;authenticated=true;}catch{return login()}await loadLive();}else{try{const saved=sessionStorage.getItem('cn-admin-draft');if(saved)data=JSON.parse(saved)}catch{}media=[{id:'brand',filename:'cloud-nest-logo.png',mime_type:'image/png',url:'/assets/cloud-nest-logo.png',alt_text:'Cloud Nest logo'},{id:'hero',filename:'hero.webp',mime_type:'image/webp',url:'/assets/hero.webp',alt_text:'Blue glass hero artwork'}];}await navigate()}catch(e){app.innerHTML=`<main class="error-screen"><h1>Unable to open your workspace.</h1><p>${esc(e.message)}</p><a class="btn" href="/admin/">Try again</a></main>`;}}
start();
})();
